package pe.pisacoma.iglesia.data

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.long
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/** content/manifest.json (generated by tools/sync-content.mjs) describes exactly the downloadable files. */
class ManifestFilesTest {
    private val content = File("../content")
    private val manifest = Json.parseToJsonElement(File(content, "manifest.json").readText()).jsonObject
    private val files = manifest["files"]!!.jsonArray.map { it.jsonObject }

    @Test fun everyListedFileExistsWithItsSize() {
        for (f in files) {
            val path = f["path"]!!.jsonPrimitive.content
            val file = File(content, path)
            assertTrue("$path missing", file.isFile)
            assertEquals(path, f["bytes"]!!.jsonPrimitive.long, file.length())
        }
    }

    @Test fun packsAreTheSixKnownOnes() =
        assertEquals(
            setOf("himnario-es", "himnario-pt", "biblia", "escuela", "buscar", "egw"),
            files.map { it["pack"]!!.jsonPrimitive.content }.toSet(),
        )

    @Test fun bibleAndEgwAreComplete() {
        assertEquals(66, files.count { it["pack"]!!.jsonPrimitive.content == "biblia" })
        assertEquals(25, files.count { it["pack"]!!.jsonPrimitive.content == "egw" })
    }

    @Test fun nothingIsBothBundledAndDownloadable() {
        for (f in files) assertFalse(File("src/main/assets", f["path"]!!.jsonPrimitive.content).exists())
    }

    @Test fun bundledCopyOfTheManifestIsIdentical() =
        assertEquals(File(content, "manifest.json").readText(), File("src/main/assets/manifest.json").readText())
}
